        "volume_title": "Old Testament",
        "book_title": "Numbers",
        "book_short_title": "Num.",
        "chapter_number": 3,
        "verse_number": 42,
        "verse_title": "Numbers 3:42",
        "verse_short_title": "Num. 3:42",
