        "volume_title": "Old Testament",
        "book_title": "Numbers",
        "book_short_title": "Num.",
        "chapter_number": 26,
        "verse_number": 45,
        "verse_title": "Numbers 26:45",
        "verse_short_title": "Num. 26:45",
