        "volume_title": "Old Testament",
        "book_title": "Job",
        "book_short_title": "Job",
        "chapter_number": 36,
        "verse_number": 22,
        "verse_title": "Job 36:22",
        "verse_short_title": "Job 36:22",
        "scripture_text": "Behold, God exalteth by his power: who teacheth like him?"
