        "volume_title": "Old Testament",
        "book_title": "Psalms",
        "book_short_title": "Ps.",
        "chapter_number": 119,
        "verse_number": 72,
        "verse_title": "Psalms 119:72",
        "verse_short_title": "Ps. 119:72",
        "scripture_text": "The law of thy mouth is better unto me than thousands of gold and silver."
