        "book_title": "Proverbs",
        "book_short_title": "Prov.",
        "chapter_number": 4,
        "verse_number": 14,
        "verse_title": "Proverbs 4:14",
        "verse_short_title": "Prov. 4:14",
        "scripture_text": "Enter not into the path of the wicked, and go not in the way of evil men."
