        "book_title": "Proverbs",
        "book_short_title": "Prov.",
        "chapter_number": 5,
        "verse_number": 2,
        "verse_title": "Proverbs 5:2",
        "verse_short_title": "Prov. 5:2",
        "scripture_text": "That thou mayest regard discretion, and that thy lips may keep knowledge."
